-- 4. Les variantes reprennent les stats de leur carte de base.
UPDATE "tcg"."cards" AS v SET "cost" = b."cost", "power" = b."power", "effect_key" = b."effect_key", "effect_params" = b."effect_params", "effect_text" = b."effect_text" FROM "tcg"."cards" AS b WHERE v."base_card_id" = b."id";

-- 5. Toutes les cartes touchées sont marquées modifiées.
UPDATE "tcg"."cards" SET "updated_at" = NOW() WHERE "effect_key" IS NOT NULL;
